<script lang="ts">
  import { browser } from '$app/environment';
  import Icon from '$lib/components/Icon.svelte';
  import MetricCard from '$lib/components/MetricCard.svelte';
  import LineChart from '$lib/components/LineChart.svelte';
  import { revenueSeries, salesSeries, trafficSources, creatorProducts, creatorTotals } from '$lib/stores/creator';

  let range = '30 days';
  let product = 'All products';
  $: ranked = [...$creatorProducts].filter((item)=>item.status==='Published' && (product === 'All products' || item.title === product)).sort((a,b)=>b.views-a.views);
  $: avgConversion = ranked.length ? ranked.reduce((sum,item)=>sum+item.conversion,0)/ranked.length : 0;
  $: ratedProducts = ranked.filter((item) => item.rating > 0);
  $: avgRating = ratedProducts.length ? ratedProducts.reduce((sum,item)=>sum+item.rating,0)/ratedProducts.length : 0;
  $: bestDay = Math.max(0, ...$revenueSeries);
  $: averageDaily = $revenueSeries.length ? $revenueSeries.reduce((sum,value)=>sum+value,0)/$revenueSeries.length : 0;
  $: averageOrder = $creatorTotals.sales ? $creatorTotals.revenue / $creatorTotals.sales : 0;
  $: hasTraffic = $trafficSources.some((source) => Number(source.value) > 0);

  function exportAnalytics() {
    if (!browser) return;
    const rows = [['Product','Status','Views','Conversion','Sales','Vendor net','Rating'], ...ranked.map((item)=>[item.title,item.status,item.views,item.conversion,item.sales,item.revenue,item.rating])];
    const csv=rows.map((row)=>row.map((value)=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
    const link=document.createElement('a');link.href=url;link.download='assetguru-creator-analytics.csv';link.click();URL.revokeObjectURL(url);
  }
</script>

<svelte:head><title>Analytics — Creator Hub — AssetGuru</title></svelte:head>
<header class="page-head"><div><span class="eyebrow">Performance intelligence</span><h1>Know what <span class="gradient-text">buyers respond to.</span></h1><p>Live product views, paid sales, conversion and vendor earnings from the production marketplace.</p></div><div class="head-actions"><select bind:value={product}><option>All products</option>{#each $creatorProducts as item}<option>{item.title}</option>{/each}</select><select bind:value={range}><option>7 days</option><option>30 days</option><option>90 days</option><option>12 months</option></select><button class="button button-secondary" type="button" onclick={exportAnalytics} disabled={!ranked.length}><Icon name="download" size={17}/> Export</button></div></header>

<div class="metrics"><MetricCard label="Vendor net revenue" value={`£${$creatorTotals.revenue.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}`} delta="Paid order items" icon="chart" tone="magenta"/><MetricCard label="Listing views" value={$creatorTotals.views.toLocaleString('en-GB')} delta="Live catalogue total" icon="eye" tone="cyan"/><MetricCard label="Conversion rate" value={`${avgConversion.toFixed(2)}%`} delta="Views to paid sales" icon="cart" tone="violet"/><MetricCard label="Average rating" value={avgRating ? `${avgRating.toFixed(1)} ★` : '—'} delta={`${ratedProducts.length} rated products`} icon="star" tone="green"/></div>

<div class="analytics-grid">
  <section class="overview glass"><div class="panel-head"><div><span class="eyebrow">Commercial trend</span><h2>Revenue and sales</h2></div></div><LineChart values={$revenueSeries} secondary={$salesSeries.map((value)=>value*20)} primaryLabel="Vendor net" secondaryLabel="Sales trend"/><div class="chart-summary"><span><small>Best recorded day</small><b>£{bestDay.toFixed(2)}</b><em>Selected series</em></span><span><small>Average daily net</small><b>£{averageDaily.toFixed(2)}</b><em>Selected series</em></span><span><small>Average net per sale</small><b>£{averageOrder.toFixed(2)}</b><em>Completed items</em></span><span><small>Paid items</small><b>{$creatorTotals.sales}</b><em>Lifetime total</em></span></div></section>

  <section class="funnel glass"><div class="panel-head"><div><span class="eyebrow">Buyer journey</span><h2>Measured conversion</h2></div></div><div class="funnel-bars"><div style="--w:100%"><span><b>{$creatorTotals.views.toLocaleString('en-GB')}</b><small>Listing views</small></span><em>100%</em></div><div style={`--w:${Math.max(42,Math.min(100,avgConversion || 0))}%`}><span><b>{$creatorTotals.sales.toLocaleString('en-GB')}</b><small>Paid product sales</small></span><em>{avgConversion.toFixed(2)}%</em></div></div><div class="insight"><Icon name="spark" size={18}/><span><b>Production telemetry only</b><small>Impressions, basket activity and campaign attribution are intentionally omitted until event tracking is connected; no estimated figures are shown.</small></span></div></section>

  <section class="traffic glass"><div class="panel-head"><div><span class="eyebrow">Discovery</span><h2>Traffic sources</h2></div></div>{#if hasTraffic}{#each $trafficSources as source}<div class="source"><span><b>{source.label}</b><small>Recorded visits</small></span><div><i data-tone={source.tone} style={`width:${source.value}%`}></i></div><strong>{source.value}%</strong></div>{/each}{:else}<div class="empty-data"><Icon name="chart" size={25}/><span><b>No attribution data yet</b><small>Traffic source percentages will appear after production event tracking records visits.</small></span></div>{/if}<a href="/creator/storefront">Improve storefront discovery →</a></section>

  <section class="audience glass"><div class="panel-head"><div><span class="eyebrow">Audience</span><h2>Buyer profile</h2></div></div><div class="empty-data"><Icon name="community" size={25}/><span><b>Privacy-safe audience data pending</b><small>Region, device and returning-buyer breakdowns are not fabricated before analytics events exist.</small></span></div></section>

  <section class="products glass"><div class="panel-head"><div><span class="eyebrow">Catalogue comparison</span><h2>Product performance</h2></div><a href="/creator/products">Manage products</a></div><div class="product-head"><span>Product</span><span>Views</span><span>Conversion</span><span>Sales</span><span>Revenue</span><span>Rating</span></div>{#if ranked.length}{#each ranked as item}<a href={`/creator/products/${item.slug}`} class="product-row"><span><img src={item.image} alt=""/><b>{item.title}</b></span><strong>{item.views.toLocaleString('en-GB')}</strong><strong>{item.conversion.toFixed(2)}%</strong><strong>{item.sales.toLocaleString('en-GB')}</strong><strong>£{item.revenue.toLocaleString('en-GB',{minimumFractionDigits:2,maximumFractionDigits:2})}</strong><em>{item.rating ? `${item.rating} ★` : 'New'}</em></a>{/each}{:else}<div class="empty-data"><Icon name="package" size={25}/><span><b>No published products</b><small>Product analytics will begin after the first approved release.</small></span></div>{/if}</section>

  <section class="searches glass"><div class="panel-head"><div><span class="eyebrow">Search demand</span><h2>Terms leading to your store</h2></div></div><div class="empty-data"><Icon name="search" size={25}/><span><b>No search events recorded</b><small>Search-term reporting will stay empty until production discovery telemetry is enabled.</small></span></div></section>
</div>
