ow{display:grid;grid-template-columns:minmax(220px,1.4fr) 75px 75px 65px 85px 55px;gap:10px;align-items:center}.product-head{min-height:34px;color:#718096;font-size:7px;text-transform:uppercase}.product-row{min-height:56px;border-top:1px solid #122a43}.product-row>span{display:flex;gap:9px;align-items:center}.product-row img{width:57px;height:38px;object-fit:cover;border-radius:6px}.product-row b,.product-row strong{font-size:8px}.product-row em{color:#24d89a;font-size:8px;font-style:normal}.searches{grid-column:2}.term{min-height:51px;display:grid;grid-template-columns:22px 1fr auto;gap:8px;align-items:center;border-top:1px solid #122a43}.term i{color:#718096;font-size:8px;font-style:normal}.term span{display:grid}.term b{font-size:8px}.term small{color:#718096;font-size:7px}.term strong{color:#00e5ff;font-size:8px}
  @media(max-width:1100px){.analytics-grid{grid-template-columns:1fr}.analytics-grid>section{grid-column:1}.metrics{grid-template-columns:repeat(2,1fr)}}
  @media(max-width:760px){.page-head{align-items:start;flex-direction:column}.head-actions{width:100%;display:grid;grid-template-columns:1fr 1fr}.head-actions .button{grid-column:1/-1}.chart-summary{grid-template-columns:repeat(2,1fr)}.chart-summary span:nth-child(3){border-left:0;border-top:1px solid #183352;padding-top:10px}.chart-summary span:nth-child(4){border-top:1px solid #183352;padding-top:10px}.products{overflow-x:auto}.product-head,.product-row{min-width:680px}}
  @media(max-width:560px){.metrics{grid-template-columns:1fr}.audience-grid{grid-template-columns:1fr}.donut{margin:auto}.source{grid-template-columns:125px 1fr 30px}}
